-- Seed data for migration 0016 — extracted from the founder's real
-- competitor research (AME29dashboard.html), same source as the earlier
-- static migration 0015/src/lib/data/competitor-intel.json (now superseded
-- by these live tables). Uses a DO block with a name->id map so
-- competitor_platform_stats rows can reference the right competitor without
-- hardcoding UUIDs. Safe to re-run: competitors upserted on
-- (business_unit_id, group_key, name), platform stats on (competitor_id, platform).
do $seed$
declare
  v_bu_id uuid;
  v_id uuid;
begin
  select id into v_bu_id from business_units where name = 'AME29';
  if v_bu_id is null then
    raise exception 'Chưa có business_unit AME29 — chạy migration 0004 trước.';
  end if;

